package tests

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/skudra-go/ant"
	"github.com/skudra-go/ant/dialect"
	"github.com/skudra-go/ant/internal/testdb"
)

var errEmailTaken = errors.New("email is taken")

// serials is a generated integer key on each database.
var serials = map[string]string{
	"postgres":  "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
	"mysql":     "BIGINT AUTO_INCREMENT PRIMARY KEY",
	"mariadb":   "BIGINT AUTO_INCREMENT PRIMARY KEY",
	"sqlite":    "INTEGER PRIMARY KEY AUTOINCREMENT",
	"sqlserver": "BIGINT IDENTITY PRIMARY KEY",
}

// Signup's hooks query and write through the root context, as code that holds a
// global db does: BeforeInsert refuses an email another signup has, and
// AfterUpdate counts the edits on the row it wrote.
type Signup struct {
	ID    int64
	Email string
	Edits int64
	root  *SignupDB
}

func (s *Signup) BeforeInsert(ctx context.Context) error {
	taken, err := s.root.Signups.Where(ant.Eq(&Signups.Email, s.Email)).Exists(ctx)
	if err != nil {
		return err
	}

	if taken {
		return errEmailTaken
	}

	return nil
}

func (s *Signup) AfterUpdate(ctx context.Context) error {
	_, err := s.root.Signups.Where(ant.Eq(&Signups.ID, s.ID)).
		Update(ctx, ant.Inc(&Signups.Edits, 1))

	return err
}

// SignupDB is a context with the signups table.
type SignupDB struct {
	ant.Context
	Signups ant.Table[Signup]
}

var Signups = ant.Fields[Signup]()

func openSignups(t *testing.T, target testdb.Target) *SignupDB {
	t.Helper()
	ctx := t.Context()

	_, err := target.DB.ExecContext(
		ctx,
		`CREATE TABLE signups (id `+serials[target.Name]+`, email VARCHAR(40) NOT NULL, edits BIGINT NOT NULL)`,
	)
	require.NoError(t, err)

	t.Cleanup(func() { _, _ = target.DB.ExecContext(context.Background(), "DROP TABLE signups") })

	db, err := ant.Open[SignupDB](ctx, target.Dialect, target.DSN)
	require.NoError(t, err)
	t.Cleanup(func() { db.Close() })

	return db
}

// A hook's ctx is bound to the transaction of its write, so what the hook runs
// with it through any context on the pool, such as a global root, runs in that
// transaction. It ran on another connection: a check for a taken email could
// not see a row inserted earlier in the same transaction, and an After hook
// that wrote its own row waited for the lock its own save held until the ctx
// ended (#144).
func TestConformanceHookRunsInItsWritesTransaction(t *testing.T) {
	testdb.ForEach(t, func(t *testing.T, target testdb.Target) {
		db := openSignups(t, target)

		t.Run("a Before hook sees the transaction's rows", func(t *testing.T) {
			ctx := t.Context()

			err := db.Tx(ctx, func(tx *SignupDB) error {
				if err := tx.Signups.Insert(ctx, &Signup{Email: "a@x", root: db}); err != nil {
					return err
				}

				return tx.Signups.Insert(ctx, &Signup{Email: "a@x", root: db})
			})
			require.ErrorIs(t, err, errEmailTaken)

			n, err := db.Signups.Count(ctx)
			require.NoError(t, err)
			require.Zero(t, n, "the transaction rolled back")
		})

		t.Run("an After hook writes its own row in the save's transaction", func(t *testing.T) {
			ctx, cancel := context.WithTimeout(t.Context(), 4*time.Second)
			defer cancel()

			require.NoError(t, db.Signups.Insert(ctx, &Signup{Email: "b@x", root: db}))

			s := ant.Session(db)

			m, err := s.Signups.Where(ant.Eq(&Signups.Email, "b@x")).First(ctx)
			require.NoError(t, err)

			m.root = db
			m.Email = "c@x"

			require.NoError(t, s.SaveChanges(ctx))

			saved, err := db.Signups.Find(ctx, m.ID)
			require.NoError(t, err)
			require.Equal(t, "c@x", saved.Email)
			require.Equal(t, int64(1), saved.Edits)
		})
	})
}

var errGizmo = errors.New("gizmo refused")

// Gizmo's BeforeInsert writes a signup through the root, and its AfterInsert
// fails, so the write and what its hooks wrote must all roll back.
type Gizmo struct {
	ID   int64
	Name string `ant:"unique"`
	root *GizmoDB
}

func (g *Gizmo) BeforeInsert(ctx context.Context) error {
	if g.Name == "missing" {
		return ant.ErrNotFound // as from a Find of what the gizmo needs
	}

	return g.root.Signups.Insert(ant.WithoutHooks(ctx), &Signup{Email: g.Name + "@x"})
}

func (g *Gizmo) AfterInsert(context.Context) error { return errGizmo }

// GizmoDB is a context with the gizmos table.
type GizmoDB struct {
	ant.Context
	Gizmos  ant.Table[Gizmo]
	Signups ant.Table[Signup]
}

var Gizmos = ant.Fields[Gizmo]()

// A Before hook runs in the write's transaction too, so what it writes rolls
// back with the write. Upsert ran BeforeInsert before it began the transaction
// its AfterInsert needs, so the hook's row stayed (#144).
func TestConformanceBeforeHookRunsInItsWritesTransaction(t *testing.T) {
	testdb.ForEach(t, func(t *testing.T, target testdb.Target) {
		ctx := t.Context()
		openSignups(t, target)

		_, err := target.DB.ExecContext(
			ctx,
			`CREATE TABLE gizmos (id `+serials[target.Name]+`, name VARCHAR(40) NOT NULL UNIQUE)`,
		)
		require.NoError(t, err)

		t.Cleanup(func() {
			_, _ = target.DB.ExecContext(context.Background(), "DROP TABLE gizmos")
		})

		db, err := ant.Open[GizmoDB](ctx, target.Dialect, target.DSN)
		require.NoError(t, err)
		t.Cleanup(func() { db.Close() })

		writes := map[string]func(g *Gizmo) error{
			"Upsert": func(g *Gizmo) error {
				_, err := db.Gizmos.Upsert(ctx, g, ant.OnConflict(&Gizmos.Name).DoNothing())

				return err
			},
			"Insert": func(g *Gizmo) error { return db.Gizmos.Insert(ctx, g) },
		}

		for name, write := range writes {
			t.Run(name, func(t *testing.T) {
				if name == "Upsert" && !has(target, dialect.OnConflict) {
					t.Skip(
						"no ON CONFLICT: Upsert is ErrUnsupported, as TestConformanceUpsert checks",
					)
				}

				_, err := db.Signups.Unfiltered().Delete(ctx)
				require.NoError(t, err)

				require.ErrorIs(t, write(&Gizmo{Name: name, root: db}), errGizmo)

				n, err := db.Signups.Count(ctx)
				require.NoError(t, err)
				require.Zero(t, n, "the hook's signup rolled back")

				n, err = db.Gizmos.Count(ctx)
				require.NoError(t, err)
				require.Zero(t, n)

				// A hook's ErrNotFound is the hook's error, not a conflict that
				// wrote nothing.
				require.ErrorIs(t, write(&Gizmo{Name: "missing", root: db}), ant.ErrNotFound)
			})
		}
	})
}
